    {t="A", q=5466, n="The Lich, Ras Frostwhisper", pn="Ras Friomúrmuro, o lich", lvl=60, req=57, xp=9950, cc=1, npc="Magistrate Marduke", pnpc="Magistrado Marduque", m=1422, x=70.57, y=74.11, pre={5465}},
    {t="C", q=5466, n="The Lich, Ras Frostwhisper", pn="Ras Friomúrmuro, o lich", lvl=60, req=57, xp=9950, cc=1, ot="i", obj="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", pobj="Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque."},
    {t="C", q=5515, n="Krastinov's Bag of Horrors", pn="Saco de Horrores de Krastinov", lvl=60, req=55, xp=6600, cc=1, ot="i", obj="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", pobj="Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff."},
