    {t="A", q=5384, n="Kirtonos the Herald", pn="Kirtonos, o Arauto", lvl=60, req=55, xp=8300, npc="Eva Sarkhoff", pnpc="Eva Sarkhoff", m=1422, x=70.22, y=73.71, pre={5515}, f={"elite"}},
    {t="C", q=5384, n="Kirtonos the Herald", pn="Kirtonos, o Arauto", lvl=60, req=55, xp=8300, ot="k", obj="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff. ", pobj="Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma.  Lute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff.", f={"elite"}},
    {t="T", q=5384, n="Kirtonos the Herald", pn="Kirtonos, o Arauto", lvl=60, req=55, xp=8300, npc="Eva Sarkhoff", pnpc="Eva Sarkhoff", m=1422, x=70.22, y=73.71, f={"elite"}},
